$('#run').onclick=async()=>{$('#run').disabled=true;$('#status').textContent='Running actual treatment/media/GPU integration…';try{await runVideoTreatmentChecks();}catch(error){window.videoTreatmentHarnessResult={passed:0,failed:1,fatal:error.message};$('#results').textContent=error.stack;$('#status').textContent='Fatal harness failure';}finally{$('#run').disabled=false;}};
